def select_words(s, n):
    if not s:
        return []
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split(" "):
        if word == "":
            continue
        consonant_count = sum(1 for char in word if char not in vowels)
        if consonant_count == n:
            result.append(word)
    return result
